-- Q02 · Segurança depois de instalar: deny-by-default, barreira admin/tester, só servidor, nada ligado, nada escrito.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH v2 AS (SELECT unnest(ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[]) AS nome),
t2 AS (SELECT c.oid, c.relname::text AS nome, c.relacl, c.relrowsecurity, c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace JOIN v2 ON v2.nome = c.relname::text WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')),
f2 AS (SELECT p.oid, p.proname::text AS nome, p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname::text = ANY (ARRAY['access_invites_pilot_guard', 'account_access_on_new_profile', 'audit_sensitive_write', 'claim_inbound_message', 'claim_pending_confirmation', 'consultant_preferences_track_opt_ins', 'consume_access_invite', 'content_access_consents_validate', 'conversation_states_touch', 'daily_digests_validate', 'effective_tier', 'email_drafts_validate', 'expire_beta_testers', 'handle_new_user', 'is_admin', 'issue_pilot_invite', 'issue_referral_invite', 'mark_pending_presented', 'merge_accounts_apply', 'merge_accounts_preview', 'pending_actions_validate', 'people_touch_email_norm', 'pilot_participant_on_invite_used', 'pilot_participants_guard', 'plan_configs_validate', 'product_feedback_validate', 'product_updates_validate', 'profiles_restrict_self_update', 'profiles_validate_billing', 'purge_admin_audit_logs', 'release_conversation_lock', 'release_pending_confirmation', 'release_unsolicited_slot', 'reminders_sync_follow_up_id', 'reserve_unsolicited_slot', 'revoke_pilot_invite', 'set_updated_at', 'subscription_events_validate', 'text_norm', 'tier_at_least', 'try_acquire_conversation_lock']::text[])),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q02-01'::text, 'as 104 tabelas V2 existem'::text, ((SELECT count(*) FROM t2) = 104)::boolean, '104'::text, ((SELECT count(*) FROM t2)::text)::text
  UNION ALL SELECT 'Q02-02'::text, 'RLS ligado em todas as tabelas de public'::text, (NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relrowsecurity))::boolean, 'todas'::text, (coalesce((SELECT string_agg(c.relname::text, ',') FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relrowsecurity), 'todas com RLS'))::text
  UNION ALL SELECT 'Q02-03'::text, 'barreira staging_gate_admin_tester em cada tabela V2 (RESTRICTIVE, ALL, anon+authenticated, has_staging_access(auth.uid()))'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.cmd = 'ALL' AND p.roles = ARRAY['anon', 'authenticated']::name[] AND p.qual ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$' AND p.with_check ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$') = 104)::boolean, '104'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.cmd = 'ALL' AND p.roles = ARRAY['anon', 'authenticated']::name[] AND p.qual ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$' AND p.with_check ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$')::text)::text
  UNION ALL SELECT 'Q02-04'::text, 'nenhuma outra política restritiva em public'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE') = 104)::boolean, '104'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE')::text)::text
  UNION ALL SELECT 'Q02-05'::text, 'anon sem nenhum privilégio (tabela ou coluna) nas tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('anon', oid, 'SELECT,INSERT,UPDATE,REFERENCES')))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('anon', oid, 'SELECT,INSERT,UPDATE,REFERENCES')), 'nenhum'))::text
  UNION ALL SELECT 'Q02-06'::text, 'authenticated (sem papel, tester e admin) sem nenhum privilégio nas tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,REFERENCES')))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,REFERENCES')), 'nenhum'))::text
  UNION ALL SELECT 'Q02-07'::text, 'nenhuma permissão para PUBLIC nas tabelas V2 (e ACL explícita em todas)'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE relacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(relacl) e WHERE e.grantee = 0)))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE relacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(relacl) e WHERE e.grantee = 0)), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-08'::text, 'service_role com SELECT/INSERT/UPDATE/DELETE e sem TRUNCATE em todas as tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE NOT (has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE')) OR has_table_privilege('service_role', oid, 'TRUNCATE')))::boolean, 'todas'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE NOT (has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE')) OR has_table_privilege('service_role', oid, 'TRUNCATE')), 'todas'))::text
  UNION ALL SELECT 'Q02-09'::text, 'as 41 funções V2 existem'::text, ((SELECT count(*) FROM f2) = 41)::boolean, '41'::text, ((SELECT count(*) FROM f2)::text)::text
  UNION ALL SELECT 'Q02-10'::text, 'nenhuma função V2 executável por anon ou authenticated'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE') OR has_function_privilege('authenticated', oid, 'EXECUTE')))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE') OR has_function_privilege('authenticated', oid, 'EXECUTE')), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-11'::text, 'nenhuma função V2 com EXECUTE para PUBLIC (ACL nula conta como PUBLIC)'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(proacl) e WHERE e.grantee = 0)))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(proacl) e WHERE e.grantee = 0)), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-12'::text, 'service_role executa todas as funções V2'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE NOT has_function_privilege('service_role', oid, 'EXECUTE')))::boolean, 'todas'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE NOT has_function_privilege('service_role', oid, 'EXECUTE')), 'todas'))::text
  UNION ALL SELECT 'Q02-13'::text, 'nenhuma política permissiva em public para PUBLIC ou anon'::text, (NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND permissive = 'PERMISSIVE' AND (roles @> ARRAY['public']::name[] OR roles @> ARRAY['anon']::name[])))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(tablename || '.' || policyname, ',') FROM pg_policies WHERE schemaname = 'public' AND permissive = 'PERMISSIVE' AND (roles @> ARRAY['public']::name[] OR roles @> ARRAY['anon']::name[])), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-14'::text, 'storage: nenhuma política para assessor-files e o bucket não existe'::text, (NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%' OR policyname ILIKE 'assessor_files%')) AND NOT EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'assessor-files'))::boolean, 'nada'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%' OR policyname ILIKE 'assessor_files%'))::text || ' políticas / ' || (SELECT count(*) FROM storage.buckets WHERE id = 'assessor-files')::text || ' bucket')::text
  UNION ALL SELECT 'Q02-15'::text, 'Realtime: nenhuma tabela V2 publicada'::text, (NOT EXISTS (SELECT 1 FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public'))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(pt.pubname || ':' || pt.tablename, ',') FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public'), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-16'::text, 'nenhum gatilho em auth.users (perfil automático em quarentena)'::text, (NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'auth.users'::regclass AND NOT tgisinternal))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(tgname::text, ',') FROM pg_trigger WHERE tgrelid = 'auth.users'::regclass AND NOT tgisinternal), 'nenhum'))::text
  UNION ALL SELECT 'Q02-17'::text, 'chaves para auth.users em public: só profiles_id_fkey (V2) e user_roles_user_id_fkey (staging)'::text, (coalesce((SELECT string_agg(cl.relname::text || '.' || x.conname::text, ',' ORDER BY cl.relname, x.conname) FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype = 'f' AND x.confrelid = 'auth.users'::regclass), '') = 'profiles.profiles_id_fkey,user_roles.user_roles_user_id_fkey')::boolean, 'profiles.profiles_id_fkey,user_roles.user_roles_user_id_fkey'::text, ((SELECT string_agg(cl.relname::text || '.' || x.conname::text, ',' ORDER BY cl.relname, x.conname) FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype = 'f' AND x.confrelid = 'auth.users'::regclass))::text
  UNION ALL SELECT 'Q02-18'::text, 'zero linhas em TODAS as 104 tabelas V2 (sem seeds, sem interruptores, sem perfis, sem envios)'::text, ((SELECT sum((xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint) FROM t2) = 0)::boolean, '0'::text, ((SELECT sum((xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint)::text || ' linhas; não vazias: ' || coalesce(string_agg(nome, ',') FILTER (WHERE (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint > 0), '-') FROM t2))::text
  UNION ALL SELECT 'Q02-19'::text, 'valores por omissão de envio/sincronização = false'::text, ((SELECT count(*) FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE (c.nome || '.' || a.attname::text) = ANY (ARRAY['access_waitlist.notify', 'calendar_sync_state.enabled', 'consultant_preferences.morning_briefing_enabled', 'consultant_preferences.evening_wrap_enabled', 'consultant_preferences.evening_checkin_enabled', 'whatsapp_proactive_tests.forced']::text[]) AND pg_get_expr(d.adbin, d.adrelid) = 'false') = 6)::boolean, '6'::text, ((SELECT count(*) FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE (c.nome || '.' || a.attname::text) = ANY (ARRAY['access_waitlist.notify', 'calendar_sync_state.enabled', 'consultant_preferences.morning_briefing_enabled', 'consultant_preferences.evening_wrap_enabled', 'consultant_preferences.evening_checkin_enabled', 'whatsapp_proactive_tests.forced']::text[]) AND pg_get_expr(d.adbin, d.adrelid) = 'false')::text)::text
  UNION ALL SELECT 'Q02-20'::text, 'colunas boolean com DEFAULT true = exatamente as previstas (nenhuma de envio)'::text, (coalesce((SELECT array_agg(k ORDER BY k COLLATE "C") FROM (SELECT c.nome || '.' || a.attname::text FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.atttypid = 'boolean'::regtype AND pg_get_expr(d.adbin, d.adrelid) = 'true') a(k)), '{}') = ARRAY['assessor_ai_logs.success', 'assessor_reasoning_traces.success', 'assistant_golden_conversations.active', 'autonomy_rules.requires_confirmation', 'dashboard_announcements.active', 'product_updates.is_published', 'promo_codes.active', 'routines.active']::text[])::boolean, 'assessor_ai_logs.success,assessor_reasoning_traces.success,assistant_golden_conversations.active,autonomy_rules.requires_confirmation,dashboard_announcements.active,product_updates.is_published,promo_codes.active,routines.active'::text, ((SELECT string_agg(k, ',' ORDER BY k COLLATE "C") FROM (SELECT c.nome || '.' || a.attname::text FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.atttypid = 'boolean'::regtype AND pg_get_expr(d.adbin, d.adrelid) = 'true') a(k)))::text
  UNION ALL SELECT 'Q02-21'::text, 'nenhum papel V2 atribuído (consultant/support_admin/super_admin)'::text, (NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin')))::boolean, 'nenhum'::text, ((SELECT count(*) FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin'))::text)::text
  UNION ALL SELECT 'Q02-22'::text, 'unaccent instalada em extensions'::text, (EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'unaccent' AND n.nspname = 'extensions'))::boolean, 'extensions'::text, (coalesce((SELECT n.nspname::text FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'unaccent'), 'não instalada'))::text
  UNION ALL SELECT 'Q02-23'::text, 'agendador: nenhuma tarefa chama funções V2'::text, (CASE WHEN to_regclass('cron.job') IS NULL THEN true ELSE (xpath('/row/c/text()', query_to_xml('select count(*) as c from cron.job where command ~* ' || quote_literal('access_invites_pilot_guard|account_access_on_new_profile|audit_sensitive_write|claim_inbound_message|claim_pending_confirmation|consultant_preferences_track_opt_ins|consume_access_invite|content_access_consents_validate|conversation_states_touch|daily_digests_validate|effective_tier|email_drafts_validate|expire_beta_testers|handle_new_user|is_admin|issue_pilot_invite|issue_referral_invite|mark_pending_presented|merge_accounts_apply|merge_accounts_preview|pending_actions_validate|people_touch_email_norm|pilot_participant_on_invite_used|pilot_participants_guard|plan_configs_validate|product_feedback_validate|product_updates_validate|profiles_restrict_self_update|profiles_validate_billing|purge_admin_audit_logs|release_conversation_lock|release_pending_confirmation|release_unsolicited_slot|reminders_sync_follow_up_id|reserve_unsolicited_slot|revoke_pilot_invite|set_updated_at|subscription_events_validate|text_norm|tier_at_least|try_acquire_conversation_lock'), false, true, '')))[1]::text::int = 0 END)::boolean, '0'::text, (CASE WHEN to_regclass('cron.job') IS NULL THEN 'sem agendador' ELSE (xpath('/row/c/text()', query_to_xml('select count(*) as c from cron.job where command ~* ' || quote_literal('access_invites_pilot_guard|account_access_on_new_profile|audit_sensitive_write|claim_inbound_message|claim_pending_confirmation|consultant_preferences_track_opt_ins|consume_access_invite|content_access_consents_validate|conversation_states_touch|daily_digests_validate|effective_tier|email_drafts_validate|expire_beta_testers|handle_new_user|is_admin|issue_pilot_invite|issue_referral_invite|mark_pending_presented|merge_accounts_apply|merge_accounts_preview|pending_actions_validate|people_touch_email_norm|pilot_participant_on_invite_used|pilot_participants_guard|plan_configs_validate|product_feedback_validate|product_updates_validate|profiles_restrict_self_update|profiles_validate_billing|purge_admin_audit_logs|release_conversation_lock|release_pending_confirmation|release_unsolicited_slot|reminders_sync_follow_up_id|reserve_unsolicited_slot|revoke_pilot_invite|set_updated_at|subscription_events_validate|text_norm|tier_at_least|try_acquire_conversation_lock'), false, true, '')))[1]::text END)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 23 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
